demo.css:
ol { list-style: symbols(cyclic "◆" "◇"); font: 15px var(--demo-sans); }
li { margin-block: var(--gap); padding-left: 6px; }
li::marker { color: var(--demo-accent); }

fallback.css:
@counter-style diamonds { system: cyclic; symbols: "◆" "◇"; suffix: " "; }
ol { list-style: diamonds; font: 15px var(--demo-sans); }
li { margin-block: var(--gap); padding-left: 6px; }
li::marker { color: var(--demo-muted); }

before.code:
@counter-style diamonds {
  system: cyclic;
  symbols: "◆" "◇";
  suffix: " ";
}
ol {
  list-style: diamonds;
}
